			if (!rider) continue;
			const orders = rider.snapshot();
			const previous = this.agentRiderViewState.get(player.playerId);
			const due = !previous || this.waveSystem.diagnostics.wave !== previous.wave || orders.needsRider && !previous.needsRider || pendingSecure !== previous.pendingSecure || terminal && !previous.terminal;
			const now = performance.now();
