		const deferMetaRecap = this.runManager?.diagnostics.secured === true && this.runManager.diagnostics.lastRunEndedReason === "secured";
		this.timeAlive = 0;
		this.simTick = 0;
		this.wrangle.reset();
		this.showroomCaptureObjective.reset();
		this.decay.reset();
		this.e6TileConsumers.reset();
		this.picnicHold.reset();
		this.deathPending = false;
		if (this.powerGraph) {
			this.powerGraph.reset(0);
			this.powerWireView?.invalidate();
		}
		this.canyonConnectAnnounced = false;
		this.canyonConnectCompletedByDeadline = false;
		this.canyonConnectFailed = false;
