		const inDeepWater = !Terrain.isCrossingStructure(actor.group.position.x, actor.group.position.z) && (Terrain.sample(actor.group.position.x, actor.group.position.z).waterClass === "deep" || this.heroInDeepwaterDiveZone(actor));
		if (!inDeepWater) return false;
