	const group = new THREE.Group();
	group.name = "BlackoutRidgeOffMapGlow";
	const light = new THREE.PointLight(glow.color, glow.intensity, 26, 2);
	light.position.set(glow.x, Terrain.visualY(glow.x, glow.z, 4), glow.z);
	group.add(light);
